param(
    [string]$ProjectRoot = (Get-Location).Path
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-FromBase64 {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Base64
    )

    $parent = Split-Path -Parent $Path

    if (
        $parent -and
        -not (Test-Path -LiteralPath $parent)
    ) {
        New-Item `
            -ItemType Directory `
            -Path $parent `
            -Force |
            Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [IO.File]::WriteAllBytes($Path, $bytes)
}

function Require-File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$RelativePath
    )

    $fullPath = Join-Path $ProjectRoot $RelativePath

    if (-not (Test-Path -LiteralPath $fullPath)) {
        throw "Arquivo obrigatorio ausente: $RelativePath"
    }
}

function Run-Installer {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,

        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    Write-Host ""
    Write-Host ("Executando " + $Name + "...") -ForegroundColor Yellow

    & powershell.exe `
        -NoProfile `
        -ExecutionPolicy Bypass `
        -File $Path `
        -ProjectRoot $ProjectRoot

    if ($LASTEXITCODE -ne 0) {
        throw "$Name terminou com codigo $LASTEXITCODE."
    }
}

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host " HIT MUSIC - INSTALADOR UNICO DA R11" -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "Projeto: $ProjectRoot"
Write-Host ""

Require-File "project.godot"
Require-File "scripts\hit_music_r7\stage.gd"
Require-File "scripts\hit_music_r7\selector.gd"
Require-File "scripts\hit_music_r7\chart_factory.gd"
Require-File "scripts\change_scenes.gd"

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$projectParent = Split-Path -Parent $ProjectRoot
$backupRoot = Join-Path `
    $projectParent `
    ("_hit_music_backup_antes_R11_" + $stamp)

New-Item `
    -ItemType Directory `
    -Path $backupRoot `
    -Force |
    Out-Null

Write-Host "Criando backup externo..." -ForegroundColor Yellow

$backupItems = @(
    "project.godot",
    "scripts",
    "scenes"
)

foreach ($relativePath in $backupItems) {
    $source = Join-Path $ProjectRoot $relativePath

    if (-not (Test-Path -LiteralPath $source)) {
        continue
    }

    $destination = Join-Path $backupRoot $relativePath
    $destinationParent = Split-Path -Parent $destination

    New-Item `
        -ItemType Directory `
        -Path $destinationParent `
        -Force |
        Out-Null

    Copy-Item `
        -LiteralPath $source `
        -Destination $destination `
        -Recurse `
        -Force
}

Write-Host ("Backup: " + $backupRoot) -ForegroundColor Green

# Impede o Godot de analisar backups locais antigos.
$localBackups = Get-ChildItem `
    -LiteralPath $ProjectRoot `
    -Directory `
    -ErrorAction SilentlyContinue |
    Where-Object {
        $_.Name -like "_backup_hit_music_*"
    }

foreach ($directory in $localBackups) {
    $ignorePath = Join-Path $directory.FullName ".gdignore"
    [IO.File]::WriteAllText(
        $ignorePath,
        "# Ignorado pelo Godot.`r`n",
        [Text.UTF8Encoding]::new($false)
    )
}

# Remove sobras posteriores que podem continuar gerando erros,
# sem tocar nos arquivos da base R8/R9/R10/R11.
$laterFiles = @(
    "scripts\hit_music_r7\stage_v12.gd",
    "scripts\hit_music_r7\stage_v13.gd",
    "scripts\hit_music_r7\selector_v12.gd",
    "scripts\hit_music_r7\selector_v13.gd",
    "scripts\hit_music_r7\theme_overlay_v12.gd",
    "scripts\hit_music_r7\theme_overlay_v13.gd",
    "scripts\hit_music_r7\effects_overlay_v13.gd",
    "scripts\hit_music_r7\game_hud_v13.gd",
    "scripts\hit_music_r7\stage_carmine_unificado.gd",
    "scripts\hit_music_r7\selector_led_persistente.gd"
)

foreach ($relativePath in $laterFiles) {
    $fullPath = Join-Path $ProjectRoot $relativePath

    if (Test-Path -LiteralPath $fullPath) {
        Remove-Item `
            -LiteralPath $fullPath `
            -Force
    }
}

$tempRoot = Join-Path `
    $env:TEMP `
    ("hit_music_r11_instalador_" + $stamp)

New-Item `
    -ItemType Directory `
    -Path $tempRoot `
    -Force |
    Out-Null

$r9Path = Join-Path $tempRoot "R9.ps1"
$r10Path = Join-Path $tempRoot "R10.ps1"
$r11Path = Join-Path $tempRoot "R11_APLICAR.ps1"
$arduinoTempPath = Join-Path $tempRoot "HitMusic_R11_CENARIO_GUIA_FLASH.ino"
$bridgeTempPath = Join-Path $tempRoot "bridge_hit_music_serial.ps1"

Write-FromBase64 `
    -Path $r9Path `
    -Base64 ""

Write-FromBase64 `
    -Path $r10Path `
    -Base64 ""

Write-FromBase64 `
    -Path $r11Path `
    -Base64 ""

Write-FromBase64 `
    -Path $arduinoTempPath `
    -Base64 ""

Write-FromBase64 `
    -Path $bridgeTempPath `
    -Base64 ""

Run-Installer `
    -Name "R9" `
    -Path $r9Path

Run-Installer `
    -Name "R10" `
    -Path $r10Path

Run-Installer `
    -Name "R11 corrigida" `
    -Path $r11Path

$arduinoFinalPath = Join-Path `
    $ProjectRoot `
    "HitMusic_R11_CENARIO_GUIA_FLASH.ino"

Copy-Item `
    -LiteralPath $arduinoTempPath `
    -Destination $arduinoFinalPath `
    -Force

$bridgeFinalPath = Join-Path `
    $ProjectRoot `
    "bridge_hit_music_serial.ps1"

Copy-Item `
    -LiteralPath $bridgeTempPath `
    -Destination $bridgeFinalPath `
    -Force

$launcherFinalPath = Join-Path `
    $ProjectRoot `
    "ABRIR_R11.ps1"

$launcherContent = @'
$ErrorActionPreference = "Stop"
$ProjectRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$Bridge = Join-Path $ProjectRoot "bridge_hit_music_serial.ps1"
$Project = Join-Path $ProjectRoot "project.godot"

Start-Process powershell.exe -ArgumentList @(
    "-NoExit",
    "-NoProfile",
    "-ExecutionPolicy",
    "Bypass",
    "-File",
    ('"' + $Bridge + '"'),
    "-ComPort",
    "COM5",
    "-BaudRate",
    "9600",
    "-VerboseLog"
)

Start-Sleep -Milliseconds 900
Start-Process $Project
'@

[IO.File]::WriteAllText(
    $launcherFinalPath,
    $launcherContent,
    [Text.UTF8Encoding]::new($false)
)

# Limpa o cache para o Godot reler a cadeia R11.
Remove-Item `
    -LiteralPath (Join-Path $ProjectRoot ".godot\editor") `
    -Recurse `
    -Force `
    -ErrorAction SilentlyContinue

Remove-Item `
    -LiteralPath (
        Join-Path `
            $ProjectRoot `
            ".godot\global_script_class_cache.cfg"
    ) `
    -Force `
    -ErrorAction SilentlyContinue

$requiredR11 = @(
    "scripts\hit_music_r7\chart_factory_v9.gd",
    "scripts\hit_music_r7\stage_v9.gd",
    "scripts\hit_music_r7\selector_v9.gd",
    "scripts\hit_music_r7\stage_v10.gd",
    "scripts\hit_music_r7\selector_v10.gd",
    "scripts\hit_music_r7\theme_overlay_v10.gd",
    "scripts\hit_music_r7\stage_v11.gd",
    "scripts\hit_music_r7\selector_v11.gd",
    "scripts\hit_music_r7\theme_overlay_v11.gd",
    "scripts\hit_music_r7\led_client.gd",
    "scripts\change_scenes.gd",
    "HitMusic_R11_CENARIO_GUIA_FLASH.ino",
    "bridge_hit_music_serial.ps1",
    "ABRIR_R11.ps1"
)

Write-Host ""
Write-Host "VALIDANDO A R11..." -ForegroundColor Cyan

foreach ($relativePath in $requiredR11) {
    $fullPath = Join-Path $ProjectRoot $relativePath

    if (-not (Test-Path -LiteralPath $fullPath)) {
        throw "Validacao falhou. Arquivo ausente: $relativePath"
    }

    Write-Host ("[OK] " + $relativePath) -ForegroundColor Green
}

$stageText = Get-Content `
    -LiteralPath (
        Join-Path `
            $ProjectRoot `
            "scripts\hit_music_r7\stage_v11.gd"
    ) `
    -Raw

if ($stageText -match "super\._finish_song") {
    throw "stage_v11 ainda possui super._finish_song invalido."
}

if ($stageText -match "super\._exit_tree") {
    throw "stage_v11 ainda possui super._exit_tree invalido."
}

if ($stageText -notmatch "GUIDE_PRELIGHT_SEC") {
    throw "A pre-iluminacao das lanes nao foi instalada."
}

$selectorText = Get-Content `
    -LiteralPath (
        Join-Path `
            $ProjectRoot `
            "scripts\hit_music_r7\selector_v11.gd"
    ) `
    -Raw

if ($selectorText -notmatch "_menu_led_timer_v11") {
    throw "O heartbeat de D2 e D3 nao foi instalado."
}

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Green
Write-Host " HIT MUSIC R11 INSTALADA COM SUCESSO" -ForegroundColor Green
Write-Host "==========================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Gameplay:" -ForegroundColor Cyan
Write-Host "  input_a = D2"
Write-Host "  input_b = D3"
Write-Host "  input_c = D4"
Write-Host "  input_d = D5"
Write-Host "  input_e = D6"
Write-Host "  input_f = D7"
Write-Host "  input_g = D8"
Write-Host "  input_h = D9"
Write-Host ""
Write-Host "TAP e HOLD acendem a lane antes da jogada."
Write-Host "D2 e D3 recebem heartbeat no seletor."
Write-Host "SLIDE nao controla LED fisico."
Write-Host ""
Write-Host "Arduino copiado para:" -ForegroundColor Cyan
Write-Host $arduinoFinalPath
Write-Host ""
Write-Host "Agora grave o Arduino R11." -ForegroundColor Yellow
Write-Host "Depois inicie ponte e Godot com:" -ForegroundColor Cyan
Write-Host "powershell -NoProfile -ExecutionPolicy Bypass -File .\ABRIR_R11.ps1"
